@pytest.mark.parametrize('state', ['UNKNOWN_EXTERNAL_STATE', 'SUPPLIER_FAILED']) @pytest.mark.parametrize('corruption', ['missing_capture', 'wrong_currency', 'wrong_binding']) def test_supplier_outcome_without_bound_capture_cannot_assert_paid(client, state, corruption): _, order, _, fid, _ = captured(client) with SessionLocal() as session: fulfillment = session.get(Fulfillment, fid) cap = session.scalar(select(Movement).where(Movement.root_payment_intent_id == fulfillment.payment_intent_id, Movement.movement_type == 'CAPTURE')) if corruption == 'missing_capture': session.delete(cap) elif corruption == 'wrong_currency': cap.currency = 'USD' else: binding = session.scalar(select(Binding).where(Binding.payment_intent_id == fulfillment.payment_intent_id)) binding.payee_id = 'another-supplier' session.commit() result = svc.record_supplier_fact(fid, {'state': state, 'evidence_reference': 'supplier://unknown'}) > assert result['unified_lifecycle']['payment_state'] == 'UNKNOWN_EXTERNAL_STATE' E AssertionError: assert 'PAID' == 'UNKNOWN_EXTERNAL_STATE' E E - UNKNOWN_EXTERNAL_STATE E + PAID
tests/test_c10_supplier_money_projection.py:27: AssertionError

