@pytest.mark.parametrize('refund_fraction,expected', [(0, 'PAID'), (2, 'PARTIALLY_REFUNDED'), (1, 'REFUNDED')]) def test_supplier_unknown_preserves_independent_bound_money_fact(client, refund_fraction, expected): _, order, _, fid, _ = captured(client) with SessionLocal() as session: fulfillment = session.get(Fulfillment, fid) iid = fulfillment.payment_intent_id cap = session.scalar(select(Movement).where(Movement.root_payment_intent_id == iid, Movement.movement_type == 'CAPTURE')) cap_id, amount = cap.money_movement_id, cap.amount_minor if refund_fraction: money.create(iid, {'movement_type': 'REFUND', 'parent_movement_id': cap_id, 'amount_minor': amount // refund_fraction, 'mode': 'CONTRACT_SIMULATOR', 'evidence': ['isolated://refund']}, 'bound-refund', 'test') result = svc.record_supplier_fact(fid, {'state': 'UNKNOWN_EXTERNAL_STATE', 'evidence_reference': 'supplier://unknown'}) > assert result['unified_lifecycle']['payment_state'] == expected E AssertionError: assert 'PAID' == 'PARTIALLY_REFUNDED' E E - PARTIALLY_REFUNDED E + PAID
